import pty, os, subprocess, time, select
def run_pty(inputs, setup=True):
    if setup: subprocess.run("/tmp/setup2.sh",shell=True,capture_output=True)
    pid, fd = pty.fork()
    if pid==0:
        os.chdir("/tmp/repro2/work")
        os.execv("/workspace/executable",["/workspace/executable","--no-update"])
    out=b""
    def read_avail(timeout=0.6):
        nonlocal out
        while True:
            r,_,_=select.select([fd],[],[],timeout)
            if not r: break
            try: data=os.read(fd,4096)
            except: break
            if not data: break
            out+=data
    time.sleep(0.4); read_avail()
    for inp in inputs:
        os.write(fd,inp); time.sleep(0.4); read_avail()
    try:
        pid2,status=os.waitpid(pid, os.WNOHANG)
        if pid2==0:
            print("still running, kill")
            os.kill(pid,9); os.waitpid(pid,0); print("inputs",inputs,"out",out); return
        print("inputs",inputs,"exit",os.waitstatus_to_exitcode(status),"out",out)
