use git2::Repository;
fn main() -> anyhow::Result<()> {
    let repo = Repository::discover(".")?;
    println!("workdir={:?} path={:?} commondir={:?} bare={}", repo.workdir(), repo.path(), repo.commondir(), repo.is_bare());
    println!("head:");
    match repo.head() {
        Ok(h) => println!("  name={:?} shorthand={:?} target={:?} symbolic={:?}", h.name(), h.shorthand(), h.target(), h.symbolic_target()),
        Err(e) => println!("  err {} code={:?} class={:?}", e, e.code(), e.class()),
    }
    for spec in std::env::args().skip(1) {
        println!("spec {spec:?}");
        match repo.resolve_reference_from_short_name(&spec) {
            Ok(r) => {
                println!("  ref name={:?} shorthand={:?} target={:?} symbolic_target={:?} is_branch={} is_remote={} is_tag={}", r.name(), r.shorthand(), r.target(), r.symbolic_target(), r.is_branch(), r.is_remote(), r.is_tag());
                match r.resolve() { Ok(rr)=> println!("  resolved name={:?} target={:?}", rr.name(), rr.target()), Err(e)=> println!("  resolve err {e}") }
            }
            Err(e) => println!("  err '{e}' code={:?} class={:?}", e.code(), e.class()),
        }
    }
    // branches upstream tests
    for b in repo.branches(None)? {
        let (branch, ty) = b?;
        let name = branch.name()?.unwrap_or("?").to_string();
        let refname = branch.get().name().unwrap_or("?").to_string();
        println!("branch {name} type={ty:?} ref={refname} target={:?}", branch.get().target());
        // upstream_name
        match repo.branch_upstream_name(&refname) {
            Ok(buf) => println!("  upstream_name={:?}", String::from_utf8_lossy(buf.as_str().unwrap_or("").as_bytes()).to_string()),
            Err(e) => println!("  upstream_name err {e} code={:?}", e.code()),
        }
        match repo.branch_upstream_remote(&refname) {
            Ok(buf) => println!("  upstream_remote={:?}", buf.as_str()),
            Err(e) => println!("  upstream_remote err {e} code={:?}", e.code()),
        }
        match branch.upstream() {
            Ok(up) => println!("  upstream branch name={:?} ref={:?} type?? target={:?}", up.name().ok().flatten(), up.get().name(), up.get().target()),
            Err(e) => println!("  upstream err {e} code={:?}", e.code()),
        }
    }
    Ok(())
}
