{"command":"cat > /workspace/src/config.rs <<'RS'
use anyhow::Context;
use git2::{Config as GitConfig, ErrorCode};
use std::fmt;
use std::str::FromStr;

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum Scope {
    All,
    Remote(String),
}

impl Scope {
    pub fn matches(&self, remote: &str) -> bool {
        match self {
            Scope::All => true,
            Scope::Remote(name) => name == remote,
        }
    }
    pub fn from_str_value(value: &str) -> Result<Self, TrimError> {
        let value = value.trim();
        if value.is_empty() {
            return Err(TrimError::ScopeParse(ScopeError::Empty));
        }
        if value == "*" {
            Ok(Scope::All)
        } else {
            Ok(Scope::Remote(value.to_owned()))
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ScopeError {
    Empty,
}

impl fmt::Display for ScopeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ScopeError::Empty => write!(f, "Scope is empty"),
        }
    }
}

impl std::error::Error for ScopeError {}

#[derive(Debug)]
pub enum TrimError {
    InvalidDeleteRangeFormat(String),
    ScopeParse(ScopeError),
    ReferenceNotBranch(Option<String>),
    Io(std::io::Error),
    BareRepository,
}

impl fmt::Display for TrimError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TrimError::InvalidDeleteRangeFormat(input) => {
                write!(f, "Invalid delete range format `{input}`")
            }
            TrimError::ScopeParse(error) => {
                write!(
                    f,
                    "Scope parse error for delete range while parsing scope: {error}"
                )
            }
            TrimError::ReferenceNotBranch(name) => {
                write!(f, "Reference {name:?} is not a branch")
            }
            TrimError::Io(error) => write!(f, "IO error: {error}"),
            TrimError::BareRepository => write!(f, "Bare repository is not supported"),
        }
    }
}

impl std::error::Error for TrimError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            TrimError::ScopeParse(error) => Some(error),
            TrimError::Io(error) => Some(error),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum DeleteRange {
    Merged(Scope),
    MergedLocal,
    MergedRemote(Scope),
    Stray,
    Diverged(Scope),
    Local,
    Remote(Scope),
}

impl FromStr for DeleteRange {
    type Err = TrimError;

    fn from_str(input: &str) -> Result<Self, Self::Err> {
        let trimmed = input.trim();
        if let Some((kind, scope)) = trimmed.split_once(':') {
            match kind.trim() {
                "merged" => Ok(DeleteRange::Merged(Scope::from_str_value(scope)?)),
                "merged-remote" => {
                    Ok(DeleteRange::MergedRemote(Scope::from_str_value(scope)?))
                }
                "diverged" => Ok(DeleteRange::Diverged(Scope::from_str_value(scope)?)),
                "remote" => Ok(DeleteRange::Remote(Scope::from_str_value(scope)?)),
                _ => Err(TrimError::InvalidDeleteRangeFormat(input.to_owned())),
            }
        } else {
            match trimmed {
                "merged-local" => Ok(DeleteRange::MergedLocal),
                "stray" => Ok(DeleteRange::Stray),
                "local" => Ok(DeleteRange::Local),
                _ => Err(TrimError::InvalidDeleteRangeFormat(input.to_owned())),
            }
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum DeleteRangeKind {
    MergedLocal,
    MergedRemote(Scope),
    Stray,
    Diverged(Scope),
    Local,
    Remote(Scope),
}

impl DeleteRange {
    pub fn expand(&self) -> Vec<DeleteRangeKind> {
        match self {
            DeleteRange::Merged(scope) => vec![
                DeleteRangeKind::MergedLocal,
                DeleteRangeKind::MergedRemote(scope.clone()),
            ],
            DeleteRange::MergedLocal => vec![DeleteRangeKind::MergedLocal],
            DeleteRange::MergedRemote(scope) => {
                vec![DeleteRangeKind::MergedRemote(scope.clone())]
            }
            DeleteRange::Stray => vec![DeleteRangeKind::Stray],
            DeleteRange::Diverged(scope) => vec![DeleteRangeKind::Diverged(scope.clone())],
            DeleteRange::Local => vec![DeleteRangeKind::Local],
            DeleteRange::Remote(scope) => vec![DeleteRangeKind::Remote(scope.clone())],
        }
    }
}

pub struct CliArgs {
    pub bases: Option<Vec<String>>,
    pub protected: Option<Vec<String>>,
    pub update: bool,
    pub no_update: bool,
    pub update_interval: Option<u64>,
    pub confirm: bool,
    pub no_confirm: bool,
    pub detach: bool,
    pub no_detach: bool,
    pub delete: Option<Vec<DeleteRange>>,
    pub dry_run: bool,
}

pub struct MergedConfig {
    pub bases: Option<Vec<String>>,
    pub protected: Vec<String>,
    pub update: bool,
    pub update_interval: u64,
    pub confirm: bool,
    pub detach: bool,
    pub delete: Vec<DeleteRange>,
    pub dry_run: bool,
}

fn config_values(config: &GitConfig, key: &str) -> anyhow::Result<Option<Vec<String>>> {
    let pattern = format!("^{}$", key.replace('.', "\\."));
    let entries = match config.entries(Some(&pattern)) {
        Ok(entries) => entries,
        Err(error) if error.code() == ErrorCode::NotFound => return Ok(None),
        Err(error) => return Err(error.into()),
    };
    let mut found = false;
    let mut values = Vec::new();
    for entry in entries {
        let entry = entry.context("failed to read git config entry")?;
        found = true;
        let value = entry.value().unwrap_or("");
        values.push(value.to_owned());
    }
    if found {
        Ok(Some(values))
    } else {
        Ok(None)
    }
}

fn split_config_values(values: Vec<String>) -> Vec<String> {
    let mut result = Vec::new();
    for value in values {
        for token in value.split(',') {
            if !token.is_empty() {
                result.push(token.to_owned());
            }
        }
    }
    result
}

fn merge_vec(
    cli: Option<Vec<String>>,
    config: &GitConfig,
    key: &str,
) -> anyhow::Result<Option<Vec<String>>> {
    if let Some(values) = cli {
        return Ok(Some(values));
    }
    match config_values(config, key)? {
        Some(values) => Ok(Some(split_config_values(values))),
        None => Ok(None),
    }
}

fn merge_bool_flags(
    positive: bool,
    negative: bool,
    name: &str,
    config: &GitConfig,
    key: &str,
    default_value: bool,
) -> anyhow::Result<bool> {
    if positive && negative {
        eprintln!("Error: Flag '{name}' and 'no-{name}' cannot be used simultaneously");
        std::process::exit(-1);
    }
    if positive {
        return Ok(true);
    }
    if negative {
        return Ok(false);
    }
    match config.get_bool(key) {
        Ok(value) => Ok(value),
        Err(error) if error.code() == ErrorCode::NotFound => Ok(default_value),
        Err(error) => Err(error.into()),
    }
}

fn merge_delete(
    cli: Option<Vec<DeleteRange>>,
    config: &GitConfig,
) -> anyhow::Result<Vec<DeleteRange>> {
    if let Some(values) = cli {
        return Ok(values);
    }
    match config_values(config, "trim.delete")? {
        Some(values) => {
            let mut result = Vec::new();
            for token in split_config_values(values) {
                result.push(DeleteRange::from_str(&token)?);
            }
            Ok(result)
        }
        None => Ok(vec![DeleteRange::Merged(Scope::Remote(
            "origin".to_owned(),
        ))]),
    }
}

impl MergedConfig {
    pub fn merge(cli: CliArgs, config: &GitConfig) -> anyhow::Result<Self> {
        let bases = merge_vec(cli.bases, config, "trim.bases")?;
        let protected = merge_vec(cli.protected, config, "trim.protected")?.unwrap_or_default();
        let update = merge_bool_flags(
            cli.update,
            cli.no_update,
            "update",
            config,
            "trim.update",
            true,
        )?;
        let update_interval = merge_update_interval(cli.update_interval, config)?;
        let confirm = merge_bool_flags(
            cli.confirm,
            cli.no_confirm,
            "confirm",
            config,
            "trim.confirm",
            true,
        )?;
        let detach = merge_bool_flags(
            cli.detach,
            cli.no_detach,
            "detach",
            config,
            "trim.detach",
            true,
        )?;
        let delete = merge_delete(cli.delete, config)?;
        Ok(Self {
            bases,
            protected,
            update,
            update_interval,
            confirm,
            detach,
            delete,
            dry_run: cli.dry_run,
        })
    }

    pub fn delete_kinds(&self) -> Vec<DeleteRangeKind> {
        let mut result = Vec::new();
        for range in &self.delete {
            for kind in range.expand() {
                if !result.contains(&kind) {
                    result.push(kind);
                }
            }
        }
        result
    }
}

fn merge_update_interval(cli: Option<u64>, config: &GitConfig) -> anyhow::Result<u64> {
    if let Some(value) = cli {
        return Ok(value);
    }
    let value = match config.get_i64("trim.updateInterval") {
        Ok(value) => value,
        Err(error) if error.code() == ErrorCode::NotFound => return Ok(5),
        Err(error) => return Err(error.into()),
    };
    if value < 0 {
        panic!("`git config trim.updateInterval` cannot be negative value")
    }
    Ok(value as u64)
}
RS
