    bases.iter().any(|base| {
        candidate == *base
            || repo
                .graph_descendant_of(*base, candidate)
                .unwrap_or(false)
    })
}

pub fn remote_parts(refname: &str) -> Option<(String, String)> {
    let display = refname.strip_prefix("refs/remotes/")?;
    let (remote, branch) = display.split_once('/')?;
    Some((remote.to_owned(), branch.to_owned()))
}

pub fn remote_display_name(refname: &str) -> Option<String> {
    refname.strip_prefix("refs/remotes/").map(ToOwned::to_owned)
}

pub fn local_head_ref_from_remote_head_target(refname: &str) -> String {
    let branch = {
        assert!(refname.starts_with("refs/remotes/"));
        let rest = refname.strip_prefix("refs/remotes/").unwrap();
        let (_remote, branch) = rest.split_once('/').unwrap_or(("", rest));
        branch.to_owned()
    };
    format!("refs/heads/{branch}")
}

fn branch_from_head_contents(contents: &str) -> Option<String> {
    let contents = contents.trim();
    let refname = contents.strip_prefix("ref: ")?;
    refname.strip_prefix("refs/heads/").map(ToOwned::to_owned)
}

pub fn worktree_branch_map(
    repo: &Repository,
) -> anyhow::Result<HashMap<String, PathBuf>> {
    let mut result = HashMap::new();
    let current_workdir = repo.workdir().map(ToOwned::to_owned);
    let commondir = repo.commondir().to_owned();

    let mut candidates: Vec<(PathBuf, String)> = Vec::new();

    if let Ok(main_repo) = Repository::open(&commondir) {
        if let Some(main_workdir) = main_repo.workdir() {
            if let Ok(head) = std::fs::read_to_string(commondir.join("HEAD")) {
                candidates.push((main_workdir.to_owned(), head));
            }
        }
    }

    let worktrees_dir = commondir.join("worktrees");
    if let Ok(read_dir) = std::fs::read_dir(&worktrees_dir) {
        let mut dirs: Vec<PathBuf> = read_dir.filter_map(|entry| entry.ok().map(|e| e.path())).collect();
        dirs.sort();
        for dir in dirs {
            let Ok(gitdir) = std::fs::read_to_string(dir.join("gitdir")) else {
                continue;
            };
            let gitdir = gitdir.trim();
            let Some(workdir) = gitdir.strip_suffix("/.git") else {
                continue;
            };
            let Ok(head) = std::fs::read_to_string(dir.join("HEAD")) else {
                continue;
            };
            candidates.push((PathBuf::from(workdir), head));
        }
    }

    // Also consult libgit2's worktree registry. This makes the current
    // worktree known even when its administrative directory has an unusual
    // layout; checked-out paths are still read from the metadata above in
    // preference to opening the worktree itself.
    if let Ok(worktrees) = repo.worktrees() {
        for name in worktrees.iter().flatten() {
            if let Ok(worktree) = repo.find_worktree(name) {
                let head_path = commondir
                    .join("worktrees")
                    .join(name)
                    .join("HEAD");
                if let Ok(head) = std::fs::read_to_string(head_path) {
                    candidates.push((worktree.path().to_owned(), head));
                }
            }
        }
    }

    for (path, head) in candidates {
        if let Some(current) = &current_workdir {
            if path == *current {
                continue;
            }
        }
        if let Some(branch) = branch_from_head_contents(&head) {
            result.entry(branch).or_insert(path);
        }
    }
    let _ = Context::default;
    Ok(result)
}
