}

fn protected_match(patterns: &[String], name: &str) -> Option<String> {
    for pattern in patterns {
        if let Ok(compiled) = glob::Pattern::new(pattern) {
            if compiled.matches(name) {
                return Some(pattern.clone());
            }
        }
    }
    None
}

fn confirm() -> Result<bool, TrimError> {
    if !std::io::stderr().is_terminal() {
        return Err(TrimError::Io(std::io::Error::new(
            std::io::ErrorKind::Other,
            "not a terminal",
        )));
    }
    let mut stderr = std::io::stderr();
    write!(stderr, "Confirm? [y/N] \u{1b}[?25l").map_err(TrimError::Io)?;
    stderr.flush().map_err(TrimError::Io)?;

    let mut tty = std::fs::File::open("/dev/tty").map_err(TrimError::Io)?;
    let fd = {
        use std::os::unix::io::AsRawFd;
        tty.as_raw_fd()
    };
    let mut original: libc::termios = unsafe { std::mem::zeroed() };
    if unsafe { libc::tcgetattr(fd, &mut original) } != 0 {
        return Err(TrimError::Io(std::io::Error::last_os_error()));
    }
    let mut raw = original;
    raw.c_lflag &= !(libc::ICANON | libc::ECHO);
    if unsafe { libc::tcsetattr(fd, libc::TCSANOW, &raw) } != 0 {
        let error = std::io::Error::last_os_error();
        return Err(TrimError::Io(error));
    }
    let mut answer = None;
    let mut read_error = None;
    while answer.is_none() {
        let mut buffer = [0_u8; 1];
        match tty.read(&mut buffer) {
            Ok(0) => {
                read_error = Some(std::io::Error::new(
                    std::io::ErrorKind::UnexpectedEof,
                    "unexpected end of file",
                ));
                break;
            }
            Ok(_) => match buffer[0] {
                b'y' | b'Y' => answer = Some(true),
                b'n' | b'N' | b'\n' | b'\r' => answer = Some(false),
                _ => {}
            },
            Err(error) => {
                read_error = Some(error);
                break;
            }
        }
    }
    unsafe {
        libc::tcsetattr(fd, libc::TCSANOW, &original);
    }
    if let Some(error) = read_error {
        return Err(TrimError::Io(error));
    }
    let yes = answer.unwrap_or(false);
    let mut stderr = std::io::stderr();
    write!(
        stderr,
        "\r\u{1b}[2KConfirm? {}\r\n\u{1b}[?25h",
        if yes { "yes" } else { "no" }
    )
    .map_err(TrimError::Io)?;
    stderr.flush().map_err(TrimError::Io)?;
    Ok(yes)
}

fn check_remote_heads(
    repo: &Repository,
    workdir: &Path,
) -> anyhow::Result<Vec<(String, String, String)>> {
    let remotes = repo.remotes()?;
    let mut mismatches = Vec::new();
    for remote in remotes.iter().flatten() {
        let output = git_output(workdir, &["ls-remote", "--symref", remote, "HEAD"])?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        let mut remote_head = None;
        for line in stdout.lines() {
            if let Some(rest) = line.strip_prefix("ref:") {
                let rest = rest.trim_start();
                let target = rest.split_whitespace().next().unwrap_or("");
                if !target.is_empty() {
                    remote_head = Some(target.to_owned());
                    break;
                }
            }
        }
        let Some(remote_head) = remote_head else {
            return Err(anyhow!("HEAD not found on {remote}"));
        };
        let local_head_refname = format!("refs/remotes/{remote}/HEAD");
        let Ok(local_reference) = repo.find_reference(&local_head_refname) else {
            continue;
        };
        let Some(local_target) = local_reference.symbolic_target().ok().flatten() else {
            continue;
        };
        let local_head = branch::local_head_ref_from_remote_head_target(local_target);
        if local_head != remote_head {
            mismatches.push((remote.to_owned(), local_head, remote_head));
        }
    }
    Ok(mismatches)
}

fn main() -> anyhow::Result<()> {
    let matches = build_cli().get_matches();
    let cli = CliArgs {
        bases: matches
            .get_many::<String>("bases")
            .map(|values| values.cloned().collect()),
        protected: matches
            .get_many::<String>("protected")
            .map(|values| values.cloned().collect()),
        update: matches.get_flag("update"),
        no_update: matches.get_flag("no-update"),
        update_interval: matches.get_one::<u64>("update-interval").copied(),
        confirm: matches.get_flag("confirm"),
        no_confirm: matches.get_flag("no-confirm"),
        detach: matches.get_flag("detach"),
        no_detach: matches.get_flag("no-detach"),
        delete: matches
            .get_many::<DeleteRange>("delete")
            .map(|values| values.cloned().collect()),
        dry_run: matches.get_flag("dry-run"),
    };
    run(cli)
}

fn run(cli: CliArgs) -> anyhow::Result<()> {
    let repo = Repository::discover(".")?;
    let remotes = repo.remotes()?;
    if remotes.is_empty() {
        return Err(anyhow!("git-trim requires at least one remote"));
    }
    let git_config = repo.config()?;
    let merged_config = MergedConfig::merge(cli, &git_config)?;
    let _ = merged_config.update_interval;

    let base_specs: Vec<String>;
    if let Some(bases) = &merged_config.bases {
        if bases.is_empty() {
            eprintln!("I found that `git config trim.bases` is empty! Try any following commands to set valid bases:");
            eprintln!(" * `git config trim.bases develop,master` for a repository.");
            eprintln!(" * `git config --global trim.bases develop,master` to set globally.");
            eprintln!(" * `git trim --bases develop,master` to set temporarily.");
            return Err(anyhow!("No base branch is found!"));
        }
        base_specs = bases.clone();
    } else {
        base_specs = deduce_auto_specs(&repo)?;
        if base_specs.is_empty() {
            eprintln!("I can't detect base branch! Try following any resolution:");
            eprintln!(" * `git remote set-head origin --auto` will help `git-trim` to automatically");
            eprintln!("   detect the base branch.");
            eprintln!("   If you see `origin/HEAD set to <base branch>` in the output of the previous");
            eprintln!("   command, then `git branch --set-upstream origin/<base branch> <base branch>`");
            eprintln!("   to set an upstream branch for <base branch> if exists.");
            println!("You also can set bases manually with any of following commands:");
            eprintln!(" * `git config trim.bases develop,master` for a repository.");
            eprintln!(" * `git config --global trim.bases develop,master` to set globally.");
            eprintln!(" * `git trim --bases develop,master` to set temporarily.");
            return Err(anyhow!("No base branch is found!"));
        }
    }

    if merged_config.update {
        if !merged_config.dry_run {
            let workdir = repo
                .workdir()
                .ok_or_else(|| anyhow::Error::new(TrimError::BareRepository))?;
            run_git(workdir, &["remote", "update", "--prune"])?;
        }
        println!();
    }
    if repo.is_bare() {
        return Err(TrimError::BareRepository.into());
    }

    let repo = Repository::discover(".")?;
    let workdir = repo
        .workdir()
        .ok_or_else(|| anyhow::Error::new(TrimError::BareRepository))?
        .to_owned();
    let head_reference = repo.head()?;
    let head_branch: Option<String> = reference_name(&head_reference).and_then(|name| {
        name.strip_prefix("refs/heads/").map(ToOwned::to_owned)
    });
    let locals = collect_locals(&repo, true)?;
    let remote_infos = collect_remotes(&repo)?;
    let bases = resolve_bases(&repo, &base_specs, &locals)?;
    let base_oids: Vec<git2::Oid> = bases
        .remote_order
        .iter()
        .map(|refname| commit_oid(&repo, refname))
        .collect::<Result<Vec<_>, _>>()?;
    let bases_empty = bases.remote_order.is_empty();
    let worktree_map = worktree_branch_map(&repo)?;
    let delete_kinds = merged_config.delete_kinds();
    let tracking_scanned = delete_kinds.iter().any(|kind| {
        matches!(
            kind,
            DeleteRangeKind::MergedLocal
                | DeleteRangeKind::MergedRemote(_)
                | DeleteRangeKind::Stray
                | DeleteRangeKind::Diverged(_)
        )
    });
    let local_scanned = delete_kinds.contains(&DeleteRangeKind::Local);
    let has_kind = |target: &DeleteRangeKind| delete_kinds.contains(target);
    let scope_scanned = |kinds: &[DeleteRangeKind], remote: &str| {
        kinds.iter().any(|kind| match kind {
            DeleteRangeKind::MergedRemote(scope) if std::mem::discriminant(kind) == std::mem::discriminant(&DeleteRangeKind::MergedRemote(Scope::All)) => scope.matches(remote),
            _ => false,
        })
    };
    let _ = scope_scanned;

    // Local branches.
    let mut local_remains: Vec<String> = Vec::new();
    let mut merged_local_deletes: Vec<LocalDelete> = Vec::new();
    let mut stray_local_deletes: Vec<LocalDelete> = Vec::new();
    let mut skipped_kinds: HashSet<u8> = HashSet::new();

    for local in &locals {
        let is_tracking = local.upstream_name.is_some();
        if is_tracking && !tracking_scanned {
            skipped_kinds.insert(1);
            local_remains.push(format!("{} *1", local.name));
            continue;
        }
        if !is_tracking && !local_scanned {
            skipped_kinds.insert(2);
            local_remains.push(format!("{} *2", local.name));
            continue;
        }

        let status = if bases_empty {
            LocalStatus::none()
        } else if local.upstream_other_ref_exists {
            LocalStatus::none()
        } else if is_tracking {
            let local_oid = commit_oid(&repo, &local.refname)?;
            let local_merged = is_merged_into_any(&repo, local_oid, &base_oids);
            if let Some(upstream_refname) = &local.upstream_refname {
                let upstream_oid = commit_oid(&repo, upstream_refname)?;
                let upstream_merged = is_merged_into_any(&repo, upstream_oid, &base_oids);
                match (local_merged, upstream_merged) {
                    (true, true) => LocalStatus {
                        kind: LocalStatusKind::MergedTracking,
                        text: "merged".to_owned(),
                        required: Some(DeleteRangeKind::MergedLocal),
                        required_text: Some("merged-local".to_owned()),
                    },
                    (true, false) => {
                        let remote = local
                            .upstream_remote
                            .clone()
                            .unwrap_or_else(|| ".".to_owned());
                        LocalStatus {
                            kind: LocalStatusKind::Diverged,
                            text: format!("diverged with {upstream_refname}"),
                            required: Some(DeleteRangeKind::Diverged(if remote == "*" {
                                Scope::All
                            } else {
                                Scope::Remote(remote.clone())
                            })),
                            required_text: Some(format!("diverged:{remote}")),
                        }
                    }
                    (false, true) => LocalStatus {
                        kind: LocalStatusKind::Stray,
                        text: "stray".to_owned(),
                        required: Some(DeleteRangeKind::Stray),
                        required_text: Some("stray".to_owned()),
                    },
                    (false, false) => LocalStatus::none(),
                }
            } else {
                // A tracking branch whose upstream reference is gone.
                if local_merged {
                    LocalStatus {
                        kind: LocalStatusKind::MergedTracking,
                        text: "merged".to_owned(),
                        required: Some(DeleteRangeKind::MergedLocal),
                        required_text: Some("merged-local".to_owned()),
                    }
                } else {
                    LocalStatus {
                        kind: LocalStatusKind::Stray,
                        text: "stray".to_owned(),
                        required: Some(DeleteRangeKind::Stray),
                        required_text: Some("stray".to_owned()),
                    }
                }
            }
        } else {
            let local_oid = commit_oid(&repo, &local.refname)?;
            if is_merged_into_any(&repo, local_oid, &base_oids) {
                LocalStatus {
                    kind: LocalStatusKind::MergedNonTracking,
                    text: "merged non-tracking".to_owned(),
                    required: Some(DeleteRangeKind::Local),
                    required_text: Some("local".to_owned()),
                }
            } else {
                LocalStatus::none()
            }
        };

        if status.kind == LocalStatusKind::None {
            local_remains.push(local.name.clone());
            continue;
        }

        // Filters, in observed precedence order.
        enum Filter {
            BaseDirect,
            TracksBase(String),
            Protected(String),
            Worktree(PathBuf),
            Head,
        }
        let filter = if bases.local_names.contains(&local.name) {
            Some(Filter::BaseDirect)
        } else if let Some(spec) = bases.tracks.get(&local.name) {
            Some(Filter::TracksBase(spec.clone()))
        } else if let Some(pattern) = protected_match(&merged_config.protected, &local.name) {
            Some(Filter::Protected(pattern))
        } else if let Some(path) = worktree_map.get(&local.name) {
            Some(Filter::Worktree(path.clone()))
        } else if head_branch.as_deref() == Some(local.name.as_str()) && !merged_config.detach {
            Some(Filter::Head)
        } else {
            None
        };

        if let Some(filter) = filter {
            let annotation = match filter {
                Filter::BaseDirect => {
                    if status.text == "merged" {
                        "[base]".to_owned()
                    } else {
                        format!("[{}, but: base]", status.text)
                    }
                }
                Filter::TracksBase(spec) => {
                    if status.text == "merged" {
                        format!("[tracks base `{spec}`]")
                    } else {
                        format!("[{}, but: tracks base `{spec}`]", status.text)
                    }
                }
                Filter::Protected(pattern) => {
                    format!("[{}, but: protected by a pattern `{pattern}`]", status.text)
                }
                Filter::Worktree(path) => {
                    format!("[{}, but: worktree at {}]", status.text, path.display())
                }
                Filter::Head => format!("[{}, but: HEAD]", status.text),
            };
            local_remains.push(format!("{} {}", local.name, annotation));
            continue;
        }

        let required = status.required.clone().unwrap();
        if has_kind(&required) {
            let oid = commit_oid(&repo, &local.refname)?;
            let delete = LocalDelete {
                name: local.name.clone(),
                refname: local.refname.clone(),
                oid,
            };
            match status.kind {
                LocalStatusKind::Stray => stray_local_deletes.push(delete),
                _ => {
                    if status.kind == LocalStatusKind::MergedNonTracking {
                        merged_local_deletes.push(delete);
                    } else {
                        merged_local_deletes.push(delete);
                    }
                }
            }
        } else {
            local_remains.push(format!(
                "{} [{}, but: delete range `{}` was not given]",
                local.name,
                status.text,
                status.required_text.clone().unwrap()
            ));
        }
    }

    // Mark non-tracking suffixes later by remembering their names.
    let non_tracking_delete_names: HashSet<String> = {
        // Names are recovered from the local list by re-checking upstream.
        let mut names = HashSet::new();
        for local in &locals {
            if local.upstream_name.is_none()
                && merged_local_deletes.iter().any(|delete| delete.name == local.name)
            {
                names.insert(local.name.clone());
            }
        }
        names
    };

    // Remote branches.
    let mut remote_remains: Vec<String> = Vec::new();
    let mut merged_remote_deletes: Vec<RemoteDelete> = Vec::new();
    let mut diverged_remote_deletes: Vec<RemoteDelete> = Vec::new();
    let mut remote_delete_all: Vec<RemoteDelete> = Vec::new();
    let mut count_skipped_remote = 0_usize;
    let mut first_skipped_remote_name = String::new();

    for remote in &remote_infos {
        let paired_locals: Vec<&LocalInfo> = locals
            .iter()
            .filter(|local| local.upstream_refname.as_deref() == Some(remote.refname.as_str()))
            .collect();
        let is_upstream = !paired_locals.is_empty();
        if is_upstream && !tracking_scanned {
            skipped_kinds.insert(1);
            remote_remains.push(format!("{} *1", remote.name));
            continue;
        }
        if !is_upstream {
            let remote_range_given = delete_kinds.iter().any(|kind| match kind {
                DeleteRangeKind::Remote(scope) => scope.matches(&remote.remote),
                _ => false,
            });
            if !remote_range_given {
                if bases_empty {
                    remote_remains.push(remote.name.clone());
                } else {
                    skipped_kinds.insert(3);
                    count_skipped_remote += 1;
                    if first_skipped_remote_name.is_empty() {
                        first_skipped_remote_name = remote.remote.clone();
                    }
                    remote_remains.push(format!("{} *3", remote.name));
                }
                continue;
            }
        }

        let status = if bases_empty {
            RemoteStatus::none()
        } else {
            let remote_oid = commit_oid(&repo, &remote.refname)?;
            let remote_merged = is_merged_into_any(&repo, remote_oid, &base_oids);
            if is_upstream {
                if remote_merged {
                    RemoteStatus {
                        kind: RemoteStatusKind::MergedUpstream,
                        text: "merged".to_owned(),
                        required: Some(DeleteRangeKind::MergedRemote(Scope::Remote(
                            remote.remote.clone(),
                        ))),
                        required_text: Some(format!("merged-remote:{}", remote.remote)),
                    }
                } else {
                    let mut any_local_merged = false;
                    for local in &paired_locals {
                        let local_oid = commit_oid(&repo, &local.refname)?;
                        if is_merged_into_any(&repo, local_oid, &base_oids) {
                            any_local_merged = true;
                            break;
                        }
                    }
                    if any_local_merged {
                        RemoteStatus {
                            kind: RemoteStatusKind::Diverged,
                            text: format!("diverged with {}", remote.server_ref),
                            required: Some(DeleteRangeKind::Diverged(Scope::Remote(
                                remote.remote.clone(),
                            ))),
                            required_text: Some(format!("diverged:{}", remote.remote)),
                        }
                    } else {
                        RemoteStatus::none()
                    }
                }
            } else if remote_merged {
                RemoteStatus {
                    kind: RemoteStatusKind::MergedNonUpstream,
                    text: "merged non-upstream".to_owned(),
                    required: Some(DeleteRangeKind::Remote(Scope::Remote(
                        remote.remote.clone(),
                    ))),
                    required_text: Some(format!("remote:{}", remote.remote)),
                }
            } else {
                RemoteStatus::none()
            }
        };

        if status.kind == RemoteStatusKind::None {
            remote_remains.push(remote.name.clone());
            continue;
        }

        enum RemoteFilter {
            Base,
            Protected(String),
        }
        let filter = if bases.remote_refnames.contains(&remote.refname) {
            Some(RemoteFilter::Base)
        } else if let Some(pattern) = protected_match(&merged_config.protected, &remote.name) {
            Some(RemoteFilter::Protected(pattern))
        } else {
            None
        };
        if let Some(filter) = filter {
            let annotation = match filter {
                RemoteFilter::Base => {
                    if status.text == "merged" {
                        "[base]".to_owned()
                    } else {
                        format!("[{}, but: base]", status.text)
                    }
                }
                RemoteFilter::Protected(pattern) => {
                    format!("[{}, but: protected by a pattern `{pattern}`]", status.text)
                }
            };
            remote_remains.push(format!("{} {}", remote.name, annotation));
            continue;
        }

        let required = status.required.clone().unwrap();
        if has_kind(&required) {
            let delete = RemoteDelete {
                remote: remote.remote.clone(),
                server_ref: remote.server_ref.clone(),
            };
            remote_delete_all.push(delete.clone());
            match status.kind {
                RemoteStatusKind::Diverged => diverged_remote_deletes.push(delete),
                _ => merged_remote_deletes.push(delete),
            }
        } else {
            remote_remains.push(format!(
                "{} [{}, but: delete range `{}` was not given]",
                remote.name,
                status.text,
                status.required_text.clone().unwrap()
            ));
        }
    }

    println!("Branches that will remain:");
    println!("  local branches:");
    for remain in &local_remains {
        println!("    {remain}");
    }
    println!("  remote references:");
    for remain in &remote_remains {
        println!("    {remain}");
    }
    if !skipped_kinds.is_empty() {
        println!("  Some branches are skipped. Consider following to scan them:");
        if skipped_kinds.contains(&1) {
            println!("    *1: Add `--delete 'merged:*'` flag.");
        }
        if skipped_kinds.contains(&2) {
            println!("    *2: Set an upstream to make it a tracking branch or add `--delete 'local'` flag.");
        }
        if skipped_kinds.contains(&3) {
            let scope = if count_skipped_remote == 1 {
                first_skipped_remote_name.clone()
            } else {
                "*".to_owned()
            };
            println!(
                "    *3: Make it upstream of a tracking branch or add `--delete 'remote:{scope}'` flag."
            );
        }
    }
    println!();

    if !merged_local_deletes.is_empty() {
        println!("Delete merged local branches:");
        for delete in &merged_local_deletes {
            if non_tracking_delete_names.contains(&delete.name) {
                println!("  - {} (non-tracking)", delete.name);
            } else {
                println!("  - {}", delete.name);
            }
        }
    }
    // Non-upstream suffixes are determined from remote status by name.
    let non_upstream_server_refs: HashSet<String> = {
        let mut refs = HashSet::new();
        for remote in &remote_infos {
            let is_upstream = locals
                .iter()
                .any(|local| local.upstream_refname.as_deref() == Some(remote.refname.as_str()));
            if !is_upstream {
                refs.insert(remote.server_ref.clone());
            }
        }
        refs
    };
    if !merged_remote_deletes.is_empty() {
        println!("Delete merged remote refs:");
        for delete in &merged_remote_deletes {
            if non_upstream_server_refs.contains(&delete.server_ref)
                && remote_infos.iter().any(|remote| {
                    remote.server_ref == delete.server_ref
                        && !locals.iter().any(|local| {
                            local.upstream_refname.as_deref() == Some(remote.refname.as_str())
                        })
                })
            {
                println!("  - {}, {} (non-upstream)", delete.remote, delete.server_ref);
            } else {
                println!("  - {}, {}", delete.remote, delete.server_ref);
            }
        }
    }
    if !stray_local_deletes.is_empty() {
        println!("Delete stray local branches:");
        for delete in &stray_local_deletes {
            println!("  - {}", delete.name);
        }
    }
    if !diverged_remote_deletes.is_empty() {
        println!("Delete diverged remote refs:");
        for delete in &diverged_remote_deletes {
            println!("  - {}, {}", delete.remote, delete.server_ref);
        }
    }

    let has_deletes = !merged_local_deletes.is_empty()
        || !stray_local_deletes.is_empty()
        || !merged_remote_deletes.is_empty()
        || !diverged_remote_deletes.is_empty();

    if has_deletes && !merged_config.dry_run && merged_config.confirm {
        let yes = confirm().map_err(anyhow::Error::new)?;
        if !yes {
            println!("Cancelled");
            return Ok(());
        }
    }

    // Delete remote branches, grouped by remote.
    if !remote_delete_all.is_empty() {
        let mut groups: Vec<(String, Vec<String>)> = Vec::new();
        for delete in &remote_delete_all {
            if let Some(group) = groups.iter_mut().find(|group| group.0 == delete.remote) {
                if !group.1.contains(&delete.server_ref) {
                    group.1.push(delete.server_ref.clone());
                }
            } else {
                groups.push((delete.remote.clone(), vec![delete.server_ref.clone()]));
            }
        }
        for (remote, refs) in &groups {
            let mut args: Vec<&str> = vec!["push", "--delete", "--no-verify"];
            if merged_config.dry_run {
                args.push("--dry-run");
            }
            args.push(remote);
            for reference in refs {
                args.push(reference);
            }
            run_git(&workdir, &args)?;
        }
    }

    // Delete local branches.
    let mut local_delete_set: HashSet<LocalDelete> = HashSet::new();
    for delete in merged_local_deletes
        .iter()
        .chain(stray_local_deletes.iter())
    {
        local_delete_set.insert(delete.clone());
    }
    for delete in &local_delete_set {
        if head_branch.as_deref() == Some(delete.name.as_str()) && merged_config.detach {
            if merged_config.dry_run {
                let commit = repo.find_commit(delete.oid)?;
                let summary = commit.summary().unwrap_or("");
                println!("Note: switching to '{}' (dry run)", delete.refname);
                println!("You are in 'detached HED' state... blah blah...");
                println!(
                    "HEAD is now at {} {} (dry run)",
                    delete.oid.to_string()[..7].to_owned(),
                    summary
                );
            } else {
                run_git(&workdir, &["checkout", &delete.refname])?;
            }
        }
        if merged_config.dry_run {
            println!("Delete branch {} (dry run).", delete.name);
        } else {
            run_git(&workdir, &["branch", "--delete", "--force", &delete.name])?;
        }
    }

    if merged_config.update {
        let mismatches = check_remote_heads(&repo, &workdir)?;
        if !mismatches.is_empty() {
            eprintln!("You are using default base branches, which is deduced from `refs/remotes/*/HEAD`s.");
            eprintln!("However, they seems to be out of sync.");
            for (remote, local_head, remote_head) in &mismatches {
                eprintln!(" * {remote}: {local_head} -> {remote_head}");
            }
            eprintln!("You can sync them with these commands:");
            for (remote, _, _) in &mismatches {
                eprintln!(" > git remote set-head {remote} --auto");
            }
            eprintln!("Or you can set base branches manually:");
            eprintln!(" * `git config trim.bases develop,master` will set base branches for git-trim for a repository.");
            eprintln!(" * `git config --global trim.bases develop,master` will set base branches for `git-trim` globally.");
            eprintln!(" * `git trim --bases develop,master` will temporarily set base branches for `git-trim`");
        }
    }
    Ok(())
}
RS
"}

actions.command:
cat > /workspace/src/main.rs <<'RS'
mod branch;
mod config;

use anyhow::{anyhow, Context};
use branch::{branch_name, commit_oid, is_merged_into_any, reference_name, remote_parts, worktree_branch_map};
use clap::{Arg, ArgAction, Command};
use config::{CliArgs, DeleteRange, DeleteRangeKind, MergedConfig, Scope, TrimError};
use git2::{BranchType, Repository};
use std::collections::{HashMap, HashSet};
use std::io::{IsTerminal, Read, Write};
use std::path::{Path, PathBuf};
use std::process::Command as ProcessCommand;
use std::str::FromStr;

fn build_cli() -> Command {
    let bases_help = "Comma separated multiple names of branches. All the other branches are compared with the upstream branches of those branches. [default: branches that tracks `git symbolic-ref refs/remotes/*/HEAD`] [config: trim.bases]";
    let bases_long_help = format!("{bases_help}\n\nThe default value is a branch that tracks `git symbolic-ref refs/remotes/*/HEAD`. They might not be reflected correctly when the HEAD branch of your remote repository is changed. You can see the changed HEAD branch name with `git remote show <remote>` and apply it to your local repository with `git remote set-head <remote> --auto`.");
    let delete_help = "Comma separated values of `<delete range>[:<remote name>]`. Delete range is one of the `merged, merged-local, merged-remote, stray, diverged, local, remote`. `:<remote name>` is only necessary to a `<delete range>` when the range is applied to remote branches. You can use `*` as `<remote name>` to delete a range of branches from all remotes. [default : `merged:origin`] [config: trim.delete]";
    let delete_long_help = format!("{delete_help}\n\n`merged` implies `merged-local,merged-remote`.\n\n`merged-local` will delete merged tracking local branches. `merged-remote:<remote>` will delete merged upstream branches from `<remote>`. `stray` will delete tracking local branches, which is not merged, but the upstream is gone. `diverged:<remote>` will delete merged tracking local branches, and their upstreams from `<remote>` even if the upstreams are not merged and diverged from local ones. `local` will delete non-tracking merged local branches. `remote:<remote>` will delete non-upstream merged remote tracking branches. Use with caution when you are using other than `merged`. It might lose changes, and even nuke repositories.");
    Command::new("git-trim")
        .version("0.4.4")
        .about("Automatically trims your tracking branches whose upstream branches are merged or stray.")
        .long_about("Automatically trims your tracking branches whose upstream branches are merged or stray.\n`git-trim` is a missing companion to the `git fetch --prune` and a proper, safer, faster alternative to your `<bash oneliner HERE>`.")
        .arg(
            Arg::new("bases")
                .short('b')
                .long("bases")
                .alias("base")
                .value_name("BASES")
                .help(bases_help)
                .long_help(bases_long_help)
                .action(ArgAction::Append)
                .value_delimiter(','),
        )
        .arg(
            Arg::new("protected")
                .short('p')
                .long("protected")
                .value_name("PROTECTED")
                .help("Comma separated multiple glob patterns (e.g. `release-*`, `feature/*`) of branches that should never be deleted. [config: trim.protected]")
                .action(ArgAction::Append)
                .value_delimiter(','),
        )
        .arg(
            Arg::new("no-update")
                .long("no-update")
                .help("Do not update remotes [config: trim.update]")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("update")
                .long("update")
                .hide(true)
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("update-interval")
                .long("update-interval")
                .value_name("UPDATE_INTERVAL")
                .help("Prevents too frequent updates. Seconds between updates in seconds. 0 to disable. [default: 5] [config: trim.updateInterval]")
                .value_parser(clap::value_parser!(u64)),
        )
        .arg(
            Arg::new("no-confirm")
                .long("no-confirm")
                .help("Do not ask confirm [config: trim.confirm]")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("confirm")
                .long("confirm")
                .hide(true)
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("no-detach")
                .long("no-detach")
                .help("Do not detach when HEAD is about to be deleted [config: trim.detach]")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("detach")
                .long("detach")
                .hide(true)
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("delete")
                .short('d')
                .long("delete")
                .value_name("DELETE")
                .help(delete_help)
                .long_help(delete_long_help)
                .action(ArgAction::Append)
                .value_delimiter(',')
                .value_parser(|value: &str| DeleteRange::from_str(value)),
        )
        .arg(
            Arg::new("dry-run")
                .long("dry-run")
                .help("Do not delete branches, show what branches will be deleted")
                .action(ArgAction::SetTrue),
        )
}

#[derive(Debug, Clone)]
struct LocalInfo {
    name: String,
    refname: String,
    upstream_name: Option<String>,
    upstream_remote: Option<String>,
    upstream_refname: Option<String>,
    upstream_other_ref_exists: bool,
}

#[derive(Debug, Clone)]
struct RemoteInfo {
    name: String,
    refname: String,
    remote: String,
    branch_path: String,
    server_ref: String,
}

fn collect_locals(repo: &Repository, fail_on_upstream_remote: bool) -> anyhow::Result<Vec<LocalInfo>> {
    let mut result = Vec::new();
    let mut branches = repo.branches(Some(BranchType::Local))?;
    for branch_result in branches {
        let (branch, _) = branch_result?;
        let Some(name) = branch_name(&branch) else {
            continue;
        };
        let refname = reference_name(branch.get()).unwrap_or_default();
        let upstream_name = match repo.branch_upstream_name(&refname) {
            Ok(buf) => buf.as_str().map(ToOwned::to_owned),
            Err(_) => None,
        };
        let mut upstream_remote = None;
        let mut upstream_refname = None;
        let mut upstream_other_ref_exists = false;
        if upstream_name.is_some() {
            match repo.branch_upstream_remote(&refname) {
                Ok(buf) => upstream_remote = buf.as_str().map(ToOwned::to_owned),
                Err(error) => {
                    if fail_on_upstream_remote {
                        return Err(error.into());
                    }
                }
            }
            upstream_refname = match branch.upstream() {
                Ok(upstream) => reference_name(upstream.get()),
                Err(_) => None,
            };
            if upstream_refname.is_none() {
                if let Some(upstream_name) = &upstream_name {
                    upstream_other_ref_exists = repo.find_reference(upstream_name).is_ok();
                }
            }
        }
        result.push(LocalInfo {
            name,
            refname,
            upstream_name,
            upstream_remote,
            upstream_refname,
            upstream_other_ref_exists,
        });
    }
    result.sort_by(|a, b| a.name.cmp(&b.name));
    Ok(result)
}

fn collect_remotes(repo: &Repository) -> anyhow::Result<Vec<RemoteInfo>> {
    let mut result = Vec::new();
    let mut branches = repo.branches(Some(BranchType::Remote))?;
    for branch_result in branches {
        let (branch, _) = branch_result?;
        if branch.get().symbolic_target().ok().flatten().is_some() {
            continue;
        }
        let Some(name) = branch_name(&branch) else {
            continue;
        };
        let refname = reference_name(branch.get()).unwrap_or_default();
        let Some((remote, branch_path)) = remote_parts(&refname) else {
            continue;
        };
        result.push(RemoteInfo {
            name,
            server_ref: format!("refs/heads/{branch_path}"),
            refname,
            remote,
            branch_path,
        });
    }
    result.sort_by(|a, b| a.name.cmp(&b.name));
    Ok(result)
}

fn deduce_auto_specs(repo: &Repository) -> anyhow::Result<Vec<String>> {
    let locals = collect_locals(repo, false)?;
    let remotes_info = collect_remotes(repo)?;
    let remotes = repo.remotes()?;
    let mut specs: Vec<String> = Vec::new();
    for remote in remotes.iter().flatten() {
        let head_refname = format!("refs/remotes/{remote}/HEAD");
        let Ok(head_reference) = repo.find_reference(&head_refname) else {
            continue;
        };
        let Some(target) = head_reference.symbolic_target().ok().flatten() else {
            continue;
        };
        let Some(remote_info) = remotes_info.iter().find(|info| info.refname == target) else {
            continue;
        };
        let tracking: Vec<&LocalInfo> = locals
            .iter()
            .filter(|local| local.upstream_refname.as_deref() == Some(target))
            .collect();
        if tracking.is_empty() {
            if !specs.contains(&remote_info.name) {
                specs.push(remote_info.name.clone());
            }
        } else {
            for local in tracking {
                if !specs.contains(&local.name) {
                    specs.push(local.name.clone());
                }
            }
        }
    }
    Ok(specs)
}

#[derive(Default)]
struct ResolvedBases {
    local_names: HashSet<String>,
    remote_refnames: HashSet<String>,
    remote_order: Vec<String>,
    tracks: HashMap<String, String>,
}

impl ResolvedBases {
    fn insert_remote(&mut self, refname: &str) {
        if self.remote_refnames.insert(refname.to_owned()) {
            self.remote_order.push(refname.to_owned());
        }
    }
}

fn resolve_bases(
    repo: &Repository,
    specs: &[String],
    locals: &[LocalInfo],
) -> anyhow::Result<ResolvedBases> {
    let mut resolved = ResolvedBases::default();
    for spec in specs {
        let reference = match repo.resolve_reference_from_short_name(spec) {
            Ok(reference) => reference,
            Err(error) if error.code() == git2::ErrorCode::NotFound => continue,
            Err(error) => return Err(error.into()),
        };
        let Some(refname) = reference_name(&reference) else {
            return Err(TrimError::ReferenceNotBranch(None).into());
        };
        if reference.is_branch() {
            let Some(local_name) = reference.shorthand().ok().flatten() else {
                continue;
            };
            let Some(local) = locals.iter().find(|local| local.name == local_name) else {
                continue;
            };
            if let Some(upstream_refname) = &local.upstream_refname {
                if upstream_refname.starts_with("refs/remotes/") {
                    resolved.local_names.insert(local.name.clone());
                    resolved.insert_remote(upstream_refname);
                }
            }
        } else if reference.is_remote() {
            let Some(shorthand) = reference.shorthand().ok().flatten() else {
                continue;
            };
            if repo.find_branch(shorthand, BranchType::Remote).is_err() {
                continue;
            }
            resolved.insert_remote(&refname);
            for local in locals
                .iter()
                .filter(|local| local.upstream_refname.as_deref() == Some(refname.as_str()))
            {
                resolved.tracks.insert(local.name.clone(), spec.clone());
            }
        } else {
            return Err(TrimError::ReferenceNotBranch(Some(refname)).into());
        }
    }
    Ok(resolved)
}

fn run_git(workdir: &Path, args: &[&str]) -> anyhow::Result<()> {
    let status = ProcessCommand::new("git")
        .arg("-C")
        .arg(workdir)
        .args(args)
        .status()?;
    if status.success() {
        Ok(())
    } else {
        let code = status.code().unwrap_or(1);
        Err(std::io::Error::from_raw_os_error(code).into())
    }
}

fn git_output(workdir: &Path, args: &[&str]) -> anyhow::Result<std::process::Output> {
    let output = ProcessCommand::new("git")
        .arg("-C")
        .arg(workdir)
        .args(args)
        .output()?;
    if output.status.success() {
        Ok(output)
    } else {
        let code = output.status.code().unwrap_or(1);
        Err(std::io::Error::from_raw_os_error(code).into())
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum LocalStatusKind {
    MergedTracking,
    MergedNonTracking,
    Stray,
    Diverged,
    None,
}

#[derive(Clone)]
struct LocalStatus {
    kind: LocalStatusKind,
    text: String,
    required: Option<DeleteRangeKind>,
    required_text: Option<String>,
}

impl LocalStatus {
    fn none() -> Self {
        Self {
            kind: LocalStatusKind::None,
            text: String::new(),
            required: None,
            required_text: None,
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum RemoteStatusKind {
    MergedUpstream,
    MergedNonUpstream,
    Diverged,
    None,
}

#[derive(Clone)]
struct RemoteStatus {
    kind: RemoteStatusKind,
    text: String,
    required: Option<DeleteRangeKind>,
    required_text: Option<String>,
}

impl RemoteStatus {
    fn none() -> Self {
        Self {
            kind: RemoteStatusKind::None,
            text: String::new(),
            required: None,
            required_text: None,
        }
    }
}

#[derive(Clone)]
struct LocalDelete {
    name: String,
    refname: String,
    oid: git2::Oid,
}

impl PartialEq for LocalDelete {
    fn eq(&self, other: &Self) -> bool {
        self.name == other.name
    }
}
impl Eq for LocalDelete {}
impl std::hash::Hash for LocalDelete {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        self.name.hash(state);
    }
}

#[derive(Clone)]
struct RemoteDelete {
    remote: String,
    server_ref: String,
}

fn protected_match(patterns: &[String], name: &str) -> Option<String> {
    for pattern in patterns {
        if let Ok(compiled) = glob::Pattern::new(pattern) {
            if compiled.matches(name) {
                return Some(pattern.clone());
            }
        }
    }
    None
}

fn confirm() -> Result<bool, TrimError> {
    if !std::io::stderr().is_terminal() {
        return Err(TrimError::Io(std::io::Error::new(
            std::io::ErrorKind::Other,
            "not a terminal",
        )));
    }
    let mut stderr = std::io::stderr();
    write!(stderr, "Confirm? [y/N] \u{1b}[?25l").map_err(TrimError::Io)?;
    stderr.flush().map_err(TrimError::Io)?;

    let mut tty = std::fs::File::open("/dev/tty").map_err(TrimError::Io)?;
    let fd = {
        use std::os::unix::io::AsRawFd;
        tty.as_raw_fd()
    };
    let mut original: libc::termios = unsafe { std::mem::zeroed() };
    if unsafe { libc::tcgetattr(fd, &mut original) } != 0 {
        return Err(TrimError::Io(std::io::Error::last_os_error()));
    }
    let mut raw = original;
    raw.c_lflag &= !(libc::ICANON | libc::ECHO);
    if unsafe { libc::tcsetattr(fd, libc::TCSANOW, &raw) } != 0 {
        let error = std::io::Error::last_os_error();
        return Err(TrimError::Io(error));
    }
    let mut answer = None;
    let mut read_error = None;
    while answer.is_none() {
        let mut buffer = [0_u8; 1];
        match tty.read(&mut buffer) {
            Ok(0) => {
                read_error = Some(std::io::Error::new(
                    std::io::ErrorKind::UnexpectedEof,
                    "unexpected end of file",
                ));
                break;
            }
            Ok(_) => match buffer[0] {
                b'y' | b'Y' => answer = Some(true),
                b'n' | b'N' | b'\n' | b'\r' => answer = Some(false),
                _ => {}
            },
            Err(error) => {
                read_error = Some(error);
                break;
            }
        }
    }
    unsafe {
        libc::tcsetattr(fd, libc::TCSANOW, &original);
    }
    if let Some(error) = read_error {
        return Err(TrimError::Io(error));
    }
    let yes = answer.unwrap_or(false);
    let mut stderr = std::io::stderr();
    write!(
        stderr,
        "\r\u{1b}[2KConfirm? {}\r\n\u{1b}[?25h",
        if yes { "yes" } else { "no" }
    )
    .map_err(TrimError::Io)?;
    stderr.flush().map_err(TrimError::Io)?;
    Ok(yes)
}

fn check_remote_heads(
    repo: &Repository,
    workdir: &Path,
) -> anyhow::Result<Vec<(String, String, String)>> {
    let remotes = repo.remotes()?;
    let mut mismatches = Vec::new();
    for remote in remotes.iter().flatten() {
        let output = git_output(workdir, &["ls-remote", "--symref", remote, "HEAD"])?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        let mut remote_head = None;
        for line in stdout.lines() {
            if let Some(rest) = line.strip_prefix("ref:") {
                let rest = rest.trim_start();
                let target = rest.split_whitespace().next().unwrap_or("");
                if !target.is_empty() {
                    remote_head = Some(target.to_owned());
                    break;
                }
            }
        }
        let Some(remote_head) = remote_head else {
            return Err(anyhow!("HEAD not found on {remote}"));
        };
        let local_head_refname = format!("refs/remotes/{remote}/HEAD");
        let Ok(local_reference) = repo.find_reference(&local_head_refname) else {
            continue;
        };
        let Some(local_target) = local_reference.symbolic_target().ok().flatten() else {
            continue;
        };
        let local_head = branch::local_head_ref_from_remote_head_target(local_target);
        if local_head != remote_head {
            mismatches.push((remote.to_owned(), local_head, remote_head));
        }
    }
    Ok(mismatches)
}

fn main() -> anyhow::Result<()> {
    let matches = build_cli().get_matches();
    let cli = CliArgs {
        bases: matches
            .get_many::<String>("bases")
            .map(|values| values.cloned().collect()),
        protected: matches
            .get_many::<String>("protected")
            .map(|values| values.cloned().collect()),
        update: matches.get_flag("update"),
        no_update: matches.get_flag("no-update"),
        update_interval: matches.get_one::<u64>("update-interval").copied(),
        confirm: matches.get_flag("confirm"),
        no_confirm: matches.get_flag("no-confirm"),
        detach: matches.get_flag("detach"),
        no_detach: matches.get_flag("no-detach"),
        delete: matches
            .get_many::<DeleteRange>("delete")
            .map(|values| values.cloned().collect()),
        dry_run: matches.get_flag("dry-run"),
    };
    run(cli)
}

fn run(cli: CliArgs) -> anyhow::Result<()> {
    let repo = Repository::discover(".")?;
    let remotes = repo.remotes()?;
    if remotes.is_empty() {
        return Err(anyhow!("git-trim requires at least one remote"));
    }
    let git_config = repo.config()?;
    let merged_config = MergedConfig::merge(cli, &git_config)?;
    let _ = merged_config.update_interval;

    let base_specs: Vec<String>;
    if let Some(bases) = &merged_config.bases {
        if bases.is_empty() {
            eprintln!("I found that `git config trim.bases` is empty! Try any following commands to set valid bases:");
            eprintln!(" * `git config trim.bases develop,master` for a repository.");
            eprintln!(" * `git config --global trim.bases develop,master` to set globally.");
            eprintln!(" * `git trim --bases develop,master` to set temporarily.");
            return Err(anyhow!("No base branch is found!"));
        }
        base_specs = bases.clone();
    } else {
        base_specs = deduce_auto_specs(&repo)?;
        if base_specs.is_empty() {
            eprintln!("I can't detect base branch! Try following any resolution:");
            eprintln!(" * `git remote set-head origin --auto` will help `git-trim` to automatically");
            eprintln!("   detect the base branch.");
            eprintln!("   If you see `origin/HEAD set to <base branch>` in the output of the previous");
            eprintln!("   command, then `git branch --set-upstream origin/<base branch> <base branch>`");
            eprintln!("   to set an upstream branch for <base branch> if exists.");
            println!("You also can set bases manually with any of following commands:");
            eprintln!(" * `git config trim.bases develop,master` for a repository.");
            eprintln!(" * `git config --global trim.bases develop,master` to set globally.");
            eprintln!(" * `git trim --bases develop,master` to set temporarily.");
            return Err(anyhow!("No base branch is found!"));
        }
    }

    if merged_config.update {
        if !merged_config.dry_run {
            let workdir = repo
                .workdir()
                .ok_or_else(|| anyhow::Error::new(TrimError::BareRepository))?;
            run_git(workdir, &["remote", "update", "--prune"])?;
        }
        println!();
    }
    if repo.is_bare() {
        return Err(TrimError::BareRepository.into());
    }

    let repo = Repository::discover(".")?;
    let workdir = repo
        .workdir()
        .ok_or_else(|| anyhow::Error::new(TrimError::BareRepository))?
        .to_owned();
    let head_reference = repo.head()?;
    let head_branch: Option<String> = reference_name(&head_reference).and_then(|name| {
        name.strip_prefix("refs/heads/").map(ToOwned::to_owned)
    });
    let locals = collect_locals(&repo, true)?;
    let remote_infos = collect_remotes(&repo)?;
    let bases = resolve_bases(&repo, &base_specs, &locals)?;
    let base_oids: Vec<git2::Oid> = bases
        .remote_order
        .iter()
        .map(|refname| commit_oid(&repo, refname))
        .collect::<Result<Vec<_>, _>>()?;
    let bases_empty = bases.remote_order.is_empty();
    let worktree_map = worktree_branch_map(&repo)?;
    let delete_kinds = merged_config.delete_kinds();
    let tracking_scanned = delete_kinds.iter().any(|kind| {
        matches!(
            kind,
            DeleteRangeKind::MergedLocal
                | DeleteRangeKind::MergedRemote(_)
                | DeleteRangeKind::Stray
                | DeleteRangeKind::Diverged(_)
        )
    });
    let local_scanned = delete_kinds.contains(&DeleteRangeKind::Local);
    let has_kind = |target: &DeleteRangeKind| delete_kinds.contains(target);
    let scope_scanned = |kinds: &[DeleteRangeKind], remote: &str| {
        kinds.iter().any(|kind| match kind {
            DeleteRangeKind::MergedRemote(scope) if std::mem::discriminant(kind) == std::mem::discriminant(&DeleteRangeKind::MergedRemote(Scope::All)) => scope.matches(remote),
            _ => false,
        })
    };
    let _ = scope_scanned;

    // Local branches.
    let mut local_remains: Vec<String> = Vec::new();
    let mut merged_local_deletes: Vec<LocalDelete> = Vec::new();
    let mut stray_local_deletes: Vec<LocalDelete> = Vec::new();
    let mut skipped_kinds: HashSet<u8> = HashSet::new();

    for local in &locals {
        let is_tracking = local.upstream_name.is_some();
        if is_tracking && !tracking_scanned {
            skipped_kinds.insert(1);
            local_remains.push(format!("{} *1", local.name));
            continue;
        }
        if !is_tracking && !local_scanned {
            skipped_kinds.insert(2);
            local_remains.push(format!("{} *2", local.name));
            continue;
        }

        let status = if bases_empty {
            LocalStatus::none()
        } else if local.upstream_other_ref_exists {
            LocalStatus::none()
        } else if is_tracking {
            let local_oid = commit_oid(&repo, &local.refname)?;
            let local_merged = is_merged_into_any(&repo, local_oid, &base_oids);
            if let Some(upstream_refname) = &local.upstream_refname {
                let upstream_oid = commit_oid(&repo, upstream_refname)?;
                let upstream_merged = is_merged_into_any(&repo, upstream_oid, &base_oids);
                match (local_merged, upstream_merged) {
                    (true, true) => LocalStatus {
                        kind: LocalStatusKind::MergedTracking,
                        text: "merged".to_owned(),
                        required: Some(DeleteRangeKind::MergedLocal),
                        required_text: Some("merged-local".to_owned()),
                    },
                    (true, false) => {
                        let remote = local
                            .upstream_remote
                            .clone()
                            .unwrap_or_else(|| ".".to_owned());
                        LocalStatus {
                            kind: LocalStatusKind::Diverged,
                            text: format!("diverged with {upstream_refname}"),
                            required: Some(DeleteRangeKind::Diverged(if remote == "*" {
                                Scope::All
                            } else {
                                Scope::Remote(remote.clone())
                            })),
                            required_text: Some(format!("diverged:{remote}")),
                        }
                    }
                    (false, true) => LocalStatus {
                        kind: LocalStatusKind::Stray,
                        text: "stray".to_owned(),
                        required: Some(DeleteRangeKind::Stray),
                        required_text: Some("stray".to_owned()),
                    },
                    (false, false) => LocalStatus::none(),
                }
            } else {
                // A tracking branch whose upstream reference is gone.
                if local_merged {
                    LocalStatus {
                        kind: LocalStatusKind::MergedTracking,
                        text: "merged".to_owned(),
                        required: Some(DeleteRangeKind::MergedLocal),
                        required_text: Some("merged-local".to_owned()),
                    }
                } else {
                    LocalStatus {
                        kind: LocalStatusKind::Stray,
                        text: "stray".to_owned(),
                        required: Some(DeleteRangeKind::Stray),
                        required_text: Some("stray".to_owned()),
                    }
                }
            }
        } else {
            let local_oid = commit_oid(&repo, &local.refname)?;
            if is_merged_into_any(&repo, local_oid, &base_oids) {
                LocalStatus {
                    kind: LocalStatusKind::MergedNonTracking,
                    text: "merged non-tracking".to_owned(),
                    required: Some(DeleteRangeKind::Local),
                    required_text: Some("local".to_owned()),
                }
            } else {
                LocalStatus::none()
            }
        };

        if status.kind == LocalStatusKind::None {
            local_remains.push(local.name.clone());
            continue;
        }

        // Filters, in observed precedence order.
        enum Filter {
            BaseDirect,
            TracksBase(String),
            Protected(String),
            Worktree(PathBuf),
            Head,
        }
        let filter = if bases.local_names.contains(&local.name) {
            Some(Filter::BaseDirect)
        } else if let Some(spec) = bases.tracks.get(&local.name) {
            Some(Filter::TracksBase(spec.clone()))
        } else if let Some(pattern) = protected_match(&merged_config.protected, &local.name) {
            Some(Filter::Protected(pattern))
        } else if let Some(path) = worktree_map.get(&local.name) {
            Some(Filter::Worktree(path.clone()))
        } else if head_branch.as_deref() == Some(local.name.as_str()) && !merged_config.detach {
            Some(Filter::Head)
        } else {
            None
        };

        if let Some(filter) = filter {
            let annotation = match filter {
                Filter::BaseDirect => {
                    if status.text == "merged" {
                        "[base]".to_owned()
                    } else {
                        format!("[{}, but: base]", status.text)
                    }
                }
                Filter::TracksBase(spec) => {
                    if status.text == "merged" {
                        format!("[tracks base `{spec}`]")
                    } else {
                        format!("[{}, but: tracks base `{spec}`]", status.text)
                    }
                }
                Filter::Protected(pattern) => {
                    format!("[{}, but: protected by a pattern `{pattern}`]", status.text)
                }
                Filter::Worktree(path) => {
                    format!("[{}, but: worktree at {}]", status.text, path.display())
                }
                Filter::Head => format!("[{}, but: HEAD]", status.text),
            };
            local_remains.push(format!("{} {}", local.name, annotation));
            continue;
        }

        let required = status.required.clone().unwrap();
        if has_kind(&required) {
            let oid = commit_oid(&repo, &local.refname)?;
            let delete = LocalDelete {
                name: local.name.clone(),
                refname: local.refname.clone(),
                oid,
            };
            match status.kind {
                LocalStatusKind::Stray => stray_local_deletes.push(delete),
                _ => {
                    if status.kind == LocalStatusKind::MergedNonTracking {
                        merged_local_deletes.push(delete);
                    } else {
                        merged_local_deletes.push(delete);
                    }
                }
            }
        } else {
            local_remains.push(format!(
                "{} [{}, but: delete range `{}` was not given]",
                local.name,
                status.text,
                status.required_text.clone().unwrap()
            ));
        }
    }

    // Mark non-tracking suffixes later by remembering their names.
    let non_tracking_delete_names: HashSet<String> = {
        // Names are recovered from the local list by re-checking upstream.
        let mut names = HashSet::new();
        for local in &locals {
            if local.upstream_name.is_none()
                && merged_local_deletes.iter().any(|delete| delete.name == local.name)
            {
                names.insert(local.name.clone());
            }
        }
        names
    };

    // Remote branches.
    let mut remote_remains: Vec<String> = Vec::new();
    let mut merged_remote_deletes: Vec<RemoteDelete> = Vec::new();
    let mut diverged_remote_deletes: Vec<RemoteDelete> = Vec::new();
    let mut remote_delete_all: Vec<RemoteDelete> = Vec::new();
    let mut count_skipped_remote = 0_usize;
    let mut first_skipped_remote_name = String::new();

    for remote in &remote_infos {
        let paired_locals: Vec<&LocalInfo> = locals
            .iter()
            .filter(|local| local.upstream_refname.as_deref() == Some(remote.refname.as_str()))
            .collect();
        let is_upstream = !paired_locals.is_empty();
        if is_upstream && !tracking_scanned {
            skipped_kinds.insert(1);
            remote_remains.push(format!("{} *1", remote.name));
            continue;
        }
        if !is_upstream {
            let remote_range_given = delete_kinds.iter().any(|kind| match kind {
                DeleteRangeKind::Remote(scope) => scope.matches(&remote.remote),
                _ => false,
            });
            if !remote_range_given {
                if bases_empty {
                    remote_remains.push(remote.name.clone());
                } else {
                    skipped_kinds.insert(3);
                    count_skipped_remote += 1;
                    if first_skipped_remote_name.is_empty() {
                        first_skipped_remote_name = remote.remote.clone();
                    }
                    remote_remains.push(format!("{} *3", remote.name));
                }
                continue;
            }
        }

        let status = if bases_empty {
            RemoteStatus::none()
        } else {
            let remote_oid = commit_oid(&repo, &remote.refname)?;
            let remote_merged = is_merged_into_any(&repo, remote_oid, &base_oids);
            if is_upstream {
                if remote_merged {
                    RemoteStatus {
                        kind: RemoteStatusKind::MergedUpstream,
                        text: "merged".to_owned(),
                        required: Some(DeleteRangeKind::MergedRemote(Scope::Remote(
                            remote.remote.clone(),
                        ))),
                        required_text: Some(format!("merged-remote:{}", remote.remote)),
                    }
                } else {
                    let mut any_local_merged = false;
                    for local in &paired_locals {
                        let local_oid = commit_oid(&repo, &local.refname)?;
                        if is_merged_into_any(&repo, local_oid, &base_oids) {
                            any_local_merged = true;
                            break;
                        }
                    }
                    if any_local_merged {
                        RemoteStatus {
                            kind: RemoteStatusKind::Diverged,
                            text: format!("diverged with {}", remote.server_ref),
                            required: Some(DeleteRangeKind::Diverged(Scope::Remote(
                                remote.remote.clone(),
                            ))),
                            required_text: Some(format!("diverged:{}", remote.remote)),
                        }
                    } else {
                        RemoteStatus::none()
                    }
                }
            } else if remote_merged {
                RemoteStatus {
                    kind: RemoteStatusKind::MergedNonUpstream,
                    text: "merged non-upstream".to_owned(),
                    required: Some(DeleteRangeKind::Remote(Scope::Remote(
                        remote.remote.clone(),
                    ))),
                    required_text: Some(format!("remote:{}", remote.remote)),
                }
            } else {
                RemoteStatus::none()
            }
        };

        if status.kind == RemoteStatusKind::None {
            remote_remains.push(remote.name.clone());
            continue;
        }

        enum RemoteFilter {
            Base,
            Protected(String),
        }
        let filter = if bases.remote_refnames.contains(&remote.refname) {
            Some(RemoteFilter::Base)
        } else if let Some(pattern) = protected_match(&merged_config.protected, &remote.name) {
            Some(RemoteFilter::Protected(pattern))
        } else {
            None
        };
        if let Some(filter) = filter {
            let annotation = match filter {
                RemoteFilter::Base => {
                    if status.text == "merged" {
                        "[base]".to_owned()
                    } else {
                        format!("[{}, but: base]", status.text)
                    }
                }
                RemoteFilter::Protected(pattern) => {
                    format!("[{}, but: protected by a pattern `{pattern}`]", status.text)
                }
            };
            remote_remains.push(format!("{} {}", remote.name, annotation));
            continue;
        }

        let required = status.required.clone().unwrap();
        if has_kind(&required) {
            let delete = RemoteDelete {
                remote: remote.remote.clone(),
                server_ref: remote.server_ref.clone(),
            };
            remote_delete_all.push(delete.clone());
            match status.kind {
                RemoteStatusKind::Diverged => diverged_remote_deletes.push(delete),
                _ => merged_remote_deletes.push(delete),
            }
        } else {
            remote_remains.push(format!(
                "{} [{}, but: delete range `{}` was not given]",
                remote.name,
                status.text,
                status.required_text.clone().unwrap()
            ));
        }
    }

    println!("Branches that will remain:");
    println!("  local branches:");
    for remain in &local_remains {
        println!("    {remain}");
    }
    println!("  remote references:");
    for remain in &remote_remains {
        println!("    {remain}");
    }
    if !skipped_kinds.is_empty() {
        println!("  Some branches are skipped. Consider following to scan them:");
        if skipped_kinds.contains(&1) {
            println!("    *1: Add `--delete 'merged:*'` flag.");
        }
        if skipped_kinds.contains(&2) {
            println!("    *2: Set an upstream to make it a tracking branch or add `--delete 'local'` flag.");
        }
        if skipped_kinds.contains(&3) {
            let scope = if count_skipped_remote == 1 {
                first_skipped_remote_name.clone()
            } else {
                "*".to_owned()
            };
            println!(
                "    *3: Make it upstream of a tracking branch or add `--delete 'remote:{scope}'` flag."
            );
        }
    }
    println!();

    if !merged_local_deletes.is_empty() {
        println!("Delete merged local branches:");
        for delete in &merged_local_deletes {
            if non_tracking_delete_names.contains(&delete.name) {
                println!("  - {} (non-tracking)", delete.name);
            } else {
                println!("  - {}", delete.name);
            }
        }
    }
    // Non-upstream suffixes are determined from remote status by name.
    let non_upstream_server_refs: HashSet<String> = {
        let mut refs = HashSet::new();
        for remote in &remote_infos {
            let is_upstream = locals
                .iter()
                .any(|local| local.upstream_refname.as_deref() == Some(remote.refname.as_str()));
            if !is_upstream {
                refs.insert(remote.server_ref.clone());
            }
        }
        refs
    };
    if !merged_remote_deletes.is_empty() {
        println!("Delete merged remote refs:");
        for delete in &merged_remote_deletes {
            if non_upstream_server_refs.contains(&delete.server_ref)
                && remote_infos.iter().any(|remote| {
                    remote.server_ref == delete.server_ref
                        && !locals.iter().any(|local| {
                            local.upstream_refname.as_deref() == Some(remote.refname.as_str())
                        })
                })
            {
                println!("  - {}, {} (non-upstream)", delete.remote, delete.server_ref);
            } else {
                println!("  - {}, {}", delete.remote, delete.server_ref);
            }
        }
    }
    if !stray_local_deletes.is_empty() {
        println!("Delete stray local branches:");
        for delete in &stray_local_deletes {
            println!("  - {}", delete.name);
        }
    }
    if !diverged_remote_deletes.is_empty() {
        println!("Delete diverged remote refs:");
        for delete in &diverged_remote_deletes {
            println!("  - {}, {}", delete.remote, delete.server_ref);
        }
    }

    let has_deletes = !merged_local_deletes.is_empty()
        || !stray_local_deletes.is_empty()
        || !merged_remote_deletes.is_empty()
        || !diverged_remote_deletes.is_empty();

    if has_deletes && !merged_config.dry_run && merged_config.confirm {
        let yes = confirm().map_err(anyhow::Error::new)?;
        if !yes {
            println!("Cancelled");
            return Ok(());
        }
    }

    // Delete remote branches, grouped by remote.
    if !remote_delete_all.is_empty() {
        let mut groups: Vec<(String, Vec<String>)> = Vec::new();
        for delete in &remote_delete_all {
            if let Some(group) = groups.iter_mut().find(|group| group.0 == delete.remote) {
                if !group.1.contains(&delete.server_ref) {
                    group.1.push(delete.server_ref.clone());
                }
            } else {
                groups.push((delete.remote.clone(), vec![delete.server_ref.clone()]));
            }
        }
        for (remote, refs) in &groups {
            let mut args: Vec<&str> = vec!["push", "--delete", "--no-verify"];
            if merged_config.dry_run {
                args.push("--dry-run");
            }
            args.push(remote);
            for reference in refs {
                args.push(reference);
            }
            run_git(&workdir, &args)?;
        }
    }

    // Delete local branches.
    let mut local_delete_set: HashSet<LocalDelete> = HashSet::new();
    for delete in merged_local_deletes
        .iter()
        .chain(stray_local_deletes.iter())
    {
        local_delete_set.insert(delete.clone());
    }
    for delete in &local_delete_set {
        if head_branch.as_deref() == Some(delete.name.as_str()) && merged_config.detach {
            if merged_config.dry_run {
                let commit = repo.find_commit(delete.oid)?;
                let summary = commit.summary().unwrap_or("");
                println!("Note: switching to '{}' (dry run)", delete.refname);
                println!("You are in 'detached HED' state... blah blah...");
                println!(
                    "HEAD is now at {} {} (dry run)",
                    delete.oid.to_string()[..7].to_owned(),
                    summary
                );
            } else {
                run_git(&workdir, &["checkout", &delete.refname])?;
            }
        }
        if merged_config.dry_run {
            println!("Delete branch {} (dry run).", delete.name);
        } else {
            run_git(&workdir, &["branch", "--delete", "--force", &delete.name])?;
        }
    }

    if merged_config.update {
        let mismatches = check_remote_heads(&repo, &workdir)?;
        if !mismatches.is_empty() {
            eprintln!("You are using default base branches, which is deduced from `refs/remotes/*/HEAD`s.");
            eprintln!("However, they seems to be out of sync.");
            for (remote, local_head, remote_head) in &mismatches {
                eprintln!(" * {remote}: {local_head} -> {remote_head}");
            }
            eprintln!("You can sync them with these commands:");
            for (remote, _, _) in &mismatches {
                eprintln!(" > git remote set-head {remote} --auto");
            }
            eprintln!("Or you can set base branches manually:");
            eprintln!(" * `git config trim.bases develop,master` will set base branches for git-trim for a repository.");
            eprintln!(" * `git config --global trim.bases develop,master` will set base branches for `git-trim` globally.");
            eprintln!(" * `git trim --bases develop,master` will temporarily set base branches for `git-trim`");
        }
    }
    Ok(())
}
