def setup(script):
    subprocess.run(script,shell=True,capture_output=True)
def run(exe,args,cwd):
    return subprocess.run(["executable"]+args, executable=exe,cwd=cwd,capture_output=True,text=True)
def case(script,cwd,args_list,label="",reset_each=True):
    print(f"### {label}")
    ok=diff=0
    for args in args_list:
        if reset_each: setup(script)
        o=run(ORIG,args,cwd)
        if reset_each: setup(script)
        n=run(NEW,args,cwd)
        ot=(o.returncode,o.stdout,o.stderr); nt=(n.returncode,n.stdout,n.stderr)
        # local deletion order lines nondeterministic: sort delete branch execution lines? For diff detection raw
        if ot==nt:
            ok+=1; print(" OK",args)
        else:
            diff+=1; print(" DIFF",args)
            if o.returncode!=n.returncode: print("  rc",o.returncode,n.returncode)
            if o.stdout!=n.stdout:
                print(''.join(difflib.unified_diff(o.stdout.splitlines(True),n.stdout.splitlines(True),"orig out","new out")))
            if o.stderr!=n.stderr:
                print(''.join(difflib.unified_diff(o.stderr.splitlines(True),n.stderr.splitlines(True),"orig err","new err")))
    print(f"### {label}: ok={ok} diff={diff}")
