                        if (line.starts_with('+') && !line.starts_with("+++"))
                            || (line.starts_with('-') && !line.starts_with("---"))
                        {
                            signature.push_str(&line.chars().filter(|ch| !ch.is_whitespace()).collect::<String>());
                            signature.push('\\n');
                        } else if line.starts_with("Binary files") || line.starts_with("GIT binary patch") {
                            signature.push_str(line);
                            signature.push('\\n');
                        }
                    }
                }
                Ok(None) => {
                    signature.push_str(&format!("blob:{}\\n", delta.new_file().id()));
                }
                Err(_) => {
                    signature.push_str(&format!("blob:{}\\n", delta.new_file().id()));
                }
            }
        }
        Ok(signature)
    }

    fn commit_signature(&mut self, oid: git2::Oid) -> anyhow::Result<String> {
        if let Some(signature) = self.commit_signatures.get(&oid) {
            return Ok(signature.clone());
        }
        let commit = self.repo.find_commit(oid)?;
        let tree = commit.tree()?;
        let signature = if commit.parent_count() == 0 {
            self.diff_signature(None, &tree)?
        } else {
            let parent = commit.parent(0)?;
            let parent_tree = parent.tree()?;
            self.diff_signature(Some(&parent_tree), &tree)?
        };
        self.commit_signatures.insert(oid, signature.clone());
        Ok(signature)
    }

    fn commits_between(&self, head: git2::Oid, upstream: git2::Oid) -> anyhow::Result<Vec<git2::Oid>> {
        let mut walk = self.repo.revwalk()?;
        walk.push(head)?;
        let _ = walk.hide(upstream);
        let mut result = Vec::new();
        for item in walk {
            result.push(item?);
        }
        Ok(result)
    }

    fn is_merged(&mut self, candidate: git2::Oid, base: git2::Oid) -> bool {
        if candidate == base {
            return true;
        }
        if let Some(result) = self.cache.get(&(candidate, base)) {
            return *result;
        }
        let result = self.is_merged_inner(candidate, base).unwrap_or(false);
        self.cache.insert((candidate, base), result);
        result
    }

    fn is_merged_inner(&mut self, candidate: git2::Oid, base: git2::Oid) -> anyhow::Result<bool> {
        if self.repo.graph_descendant_of(base, candidate).unwrap_or(false) {
            return Ok(true);
        }
        let candidate_unique = self.commits_between(candidate, base)?;
        let mut candidate_signatures = Vec::new();
        for oid in &candidate_unique {
            let commit = self.repo.find_commit(*oid)?;
            if commit.parent_count() > 1 {
                continue;
            }
            candidate_signatures.push(self.commit_signature(*oid)?);
        }
        if candidate_signatures.is_empty() {
            return Ok(true);
        }
        let base_unique = self.commits_between(base, candidate)?;
        let mut base_signatures = HashSet::new();
        for oid in &base_unique {
            let signature = self.commit_signature(*oid)?;
            if !signature.is_empty() {
                base_signatures.insert(signature);
            }
        }
        if candidate_signatures.iter().all(|signature| !signature.is_empty() && base_signatures.contains(signature)) {
            return Ok(true);
        }
        // Squash-merge detection: the candidate's cumulative change may
        // have been incorporated as a single commit on the base.
        let Ok(merge_base_oid) = self.repo.merge_base(candidate, base) else {
            return Ok(false);
        };
        let merge_base_commit = self.repo.find_commit(merge_base_oid)?;
        let merge_base_tree = merge_base_commit.tree()?;
        let candidate_commit = self.repo.find_commit(candidate)?;
        let candidate_tree = candidate_commit.tree()?;
        let aggregate = self.diff_signature(Some(&merge_base_tree), &candidate_tree)?;
        if aggregate.is_empty() {
            return Ok(false);
        }
        Ok(base_signatures.contains(&aggregate))
    }

    fn is_merged_into_any(&mut self, candidate: git2::Oid, bases: &[git2::Oid]) -> bool {
        bases.iter().any(|base| self.is_merged(candidate, *base))
    }
}

